import { effectiveProps, type ArchNode } from "../graph";
import { ROUTING_KINDS, type Model } from "./model";
import { fanOutPlan, routingTargets } from "./plan";
import type { Propagation } from "./propagate";
import { int, pct, plural, rho as fmtRho } from "./format";

/**
 * One sentence per node, built from templates with the actual inputs and results
 * (docs/09 step 7). Never generated by an LLM.
 */

const SUGGESTION: Partial<Record<ArchNode["kind"], string>> = {
  lb: "add load balancer replicas",
  gateway: "add gateway replicas",
  service: "add replicas",
  worker: "add replicas",
  search: "add replicas",
  cache: "add cache replicas",
  nosql: "add shards",
  queue: "add queue capacity",
  objectstore: "put a CDN in front of it",
  external: "put a cache or a queue in front of it",
  cdn: "add CDN capacity",
};

function served(prop: Propagation, id: string) {
  const a = prop.arrivals.get(id)!;
  const e = prop.queueing.get(id)!.errorRate;
  return { read: a.read * (1 - e), write: a.write * (1 - e) };
}

function headroom(rhoValue: number): string {
  return `: under 10% headroom, so latency is ${(1 / (1 - rhoValue)).toFixed(1)}× the unloaded value`;
}

function explainDown(model: Model, prop: Propagation, node: ArchNode): string {
  const arrivals = prop.arrivals.get(node.id)!;
  if (node.kind === "client") return "Down: no traffic from these users.";

  const cluster = model.clusters.get(node.id);
  if (cluster) {
    if (cluster.promoted) {
      const label = model.byId.get(cluster.promoted)!.label;
      return `Primary down: ${label} promoted. Writes now go to ${label}.`;
    }
    if (cluster.pool.length === 0) return "Primary down and no healthy replica: reads and writes fail.";
    const reason = node.props.failover ? "no healthy replica to promote" : "no failover";
    return `Primary down, ${reason}: writes fail; reads are served by ${plural(cluster.pool.length, "replica")}.`;
  }

  if (node.kind === "queue") return `Queue down: ${int(arrivals.read + arrivals.write)} msg/s rejected.`;

  const parents = (model.incoming.get(node.id) ?? []).map((e) => model.byId.get(e.from)!);

  if (node.kind === "cache") {
    const consumer = parents.find((p) => !ROUTING_KINDS.has(p.kind) && fanOutPlan(model, p.id, "read").cacheAside);
    if (consumer) {
      const reads = served(prop, consumer.id).read;
      const stores = fanOutPlan(model, consumer.id, "read").stores.map((e) => model.byId.get(e.to)!.label);
      const before = reads * (1 - effectiveProps(node).hitRate);
      return `Cache down: ${consumer.label} sends all ${int(reads)} reads/s to ${stores.join(" and ")} instead of about ${int(before)}.`;
    }
  }

  const queueParent = parents.find((p) => p.kind === "queue");
  if (queueParent) {
    return `Consumers down: backlog grows by ${int(prop.backlog.get(queueParent.id) ?? 0)} msg/s; requests still succeed (async).`;
  }

  const router = parents.find((p) => ROUTING_KINDS.has(p.kind) || p.kind === "cdn");
  if (router) {
    const healthy = new Set<string>();
    for (const cls of ["read", "write"] as const) {
      for (const t of routingTargets(model, router.id, cls).targets) healthy.add(t.edge.to);
    }
    if (healthy.size > 0) return `Down: traffic rerouted to ${plural(healthy.size, "healthy target")}.`;
    const s = served(prop, router.id);
    return `Down: no healthy target, so ${int(s.read + s.write)} rps fail at ${router.label}.`;
  }

  const total = arrivals.read + arrivals.write;
  return total > 0 ? `Down: ${int(total)} rps that depend on it fail.` : "Down.";
}

export function explain(model: Model, prop: Propagation, id: string): string {
  const node = model.byId.get(id)!;
  const q = prop.queueing.get(id)!;
  const a = prop.arrivals.get(id)!;
  const p = effectiveProps(node);
  const total = a.read + a.write;

  if (node.status === "down") return explainDown(model, prop, node);
  if (node.kind === "client") return `Sends ${int(total)} rps (${int(a.read)} reads, ${int(a.write)} writes).`;
  if (q.status === "idle") return "No traffic reaches this component.";

  if (node.kind === "queue") {
    const backlog = prop.backlog.get(id) ?? 0;
    if (backlog > 0) {
      const inflow = total * (1 - q.errorRate);
      const consumers = (model.out.get(id) ?? []).map((e) => model.byId.get(e.to)!).filter((n) => n.status === "up");
      const advice =
        consumers.length === 1
          ? `Add ${Math.ceil(backlog / effectiveProps(consumers[0]!).capacityRps)} more ${consumers[0]!.label} replicas.`
          : consumers.length === 0
            ? "Add a consumer."
            : "Add consumer capacity.";
      return `Consumers drain ${int(inflow - backlog)}/s of ${int(inflow)}/s, so the backlog grows by ${int(backlog)} msg/s. ${advice}`;
    }
  }

  const clusterPrimary = model.clusterOf.get(id);
  const promotedPrefix =
    clusterPrimary && model.clusters.get(clusterPrimary)?.promoted === id
      ? `Promoted to primary after ${model.byId.get(clusterPrimary)!.label} went down. `
      : "";

  let base: string;
  let suggestion: string | undefined;
  if (node.kind === "sql") {
    base = `${int(a.read)} reads/s + ${int(a.write)} writes/s on ${plural(p.shards, "shard")} (capacity ${int(p.readCapacity)} reads / ${int(p.writeCapacity)} writes per shard) → ρ = ${fmtRho(q.rho)}`;
    const writeShare = a.write / (p.shards * p.writeCapacity);
    const readShare = a.read / (p.shards * p.readCapacity);
    suggestion = writeShare >= readShare ? "shard the database, or reduce writes" : "add read replicas or a cache";
  } else if (node.kind === "cache" && q.status !== "saturated") {
    const h = p.hitRate;
    return `${promotedPrefix}Hit rate ${pct(h)}%: absorbs ${int(a.read * h)} of ${int(a.read)} reads/s (ρ = ${fmtRho(q.rho)}).`;
  } else if (node.kind === "nosql") {
    base = `${int(total)} rps on ${plural(p.shards, "shard")} × ${int(p.capacityRps)} rps → ρ = ${fmtRho(q.rho)}`;
    suggestion = SUGGESTION.nosql;
  } else {
    base = `${int(total)} rps on ${int(p.replicas)} × ${int(p.capacityRps)} rps → ρ = ${fmtRho(q.rho)}`;
    suggestion = SUGGESTION[node.kind];
  }

  if (q.status === "saturated" && q.errorRate < 0.0005) {
    return `${promotedPrefix}${base}: running at full capacity with no headroom.${suggestion ? ` Consider: ${suggestion}.` : ""}`;
  }
  if (q.status === "saturated") {
    return `${promotedPrefix}${base} → ${pct(q.errorRate)}% of its requests dropped.${suggestion ? ` Consider: ${suggestion}.` : ""}`;
  }
  if (q.status === "hot") return `${promotedPrefix}${base}${headroom(q.rho)}.`;
  return `${promotedPrefix}${base}.`;
}
